  // ==================== 方位计算 ====================
  function dirOf(lat, lng, c) {
    if (!c) return '';
    const T = DT[c.sz] || [2, 3];
    const dLat = lat - c.lat, dLng = lng - c.lng;
    let ns = '', ew = '';
    if (dLat > T[0]) ns = '北';
    else if (dLat < -T[0]) ns = '南';
    if (dLng > T[1]) ew = '东';
    else if (dLng < -T[1]) ew = '西';
    if (!ns && !ew) return '中部';
    return ns + ew + '部';
  }

  self.GeoDir = { DT, CC, CTR, cnMap, dirOf, REG };
